    [Theory]
    [MemberData(nameof(Contexts))]
    public async Task DeclarationsAndReferencesPreserveContext(
        bool prepared, string name, string script, int status, string outputHex,
        string diagnostic, string? source, string filesJson)
    {
        var memory = new MemoryGovernor(1024 * 1024);
        await using var host = new TestHost { MemoryBudget = memory };
        if (source != null) host.AddFile("/unit", source);
        using var owner = memory.CreateScope();
        using var cancel = new CancellationTokenSource(TimeSpan.FromSeconds(10));
        var result = prepared
            ? await new Engine().RunAsync(new Eval(Parser.Parse(script)), host, owner, cancel.Token)
            : await BashScript.RunAsync(host, script, EvaluationOptions.Default, cancel.Token);

        Assert.Equal(status, result.ExitCode);
        Assert.Equal(Convert.FromHexString(outputHex), host.StandardOutput.Content.ToArray());
        Assert.Equal(diagnostic, host.StandardError.TextContent);
        var files = JsonSerializer.Deserialize<SortedDictionary<string, string>>(filesJson)
            ?? throw new InvalidDataException();
        Assert.Equal(files.ToArray(), host.CaptureEntries()
            .Select(p => new KeyValuePair<string, string>(p.Key, p.Value.Kind + ":" + p.Value.ContentHex)).ToArray());
        Assert.True(host.OpenFileCount == 0, name + ": descriptors must close");
        owner.Dispose();
        Assert.Equal(0, memory.ReservedBytes);
    }

    [Theory]
    [InlineData("", "-n", null, null, false, false, false)]
    [InlineData("a=old; ", "-nx", "old", null, false, false, false)]
    [InlineData("a=old; ", "-nr", "old", null, false, false, false)]
    [InlineData("a=old; ", "-nrx", "old", null, false, false, false)]
    [InlineData("export a=old; ", "-nr", "old", null, false, true, false)]
    [InlineData("readonly a=old; ", "-nx", "old", null, false, false, true)]
    [InlineData("b=kept; declare -n a=b; ", "-nrx", null, "b", false, false, false)]
    [InlineData("a=(old second); ", "-nrx", null, null, true, false, false)]
    public async Task RejectedInitializerPreservesBindingKindValueAndAttributes(
        string setup, string flags, string? scalar, string? target, bool indexed, bool exported, bool readOnly)
    {
        var memory = new MemoryGovernor(1024 * 1024);
        await using var host = new TestHost { MemoryBudget = memory };
        using var owner = memory.CreateScope();
        var evaluation = new Eval(Parser.Parse(setup + "declare " + flags + " a=a"));
        using var cancel = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        var result = await new Engine().RunAsync(evaluation, host, owner, cancel.Token);

        Assert.Equal(1, result.ExitCode);
        Assert.Equal(scalar != null, evaluation.Variables.ContainsKey("a"));
        if (scalar != null) Assert.Equal(ShellValue.FromText(scalar), evaluation.Variables["a"]);
        Assert.Equal(target != null, evaluation.Namerefs.ContainsKey("a"));
        if (target != null)
        {
            Assert.Equal(ShellValue.FromText(target), evaluation.Namerefs["a"]);
            Assert.Equal(ShellValue.FromText("kept"), evaluation.Variables["b"]);
        }
        Assert.Equal(indexed, evaluation.IndexedArrays.ContainsKey("a"));
        if (indexed) Assert.Equal([ShellValue.FromText("old"), ShellValue.FromText("second")], evaluation.IndexedArrays["a"]);
        Assert.False(evaluation.AssociativeArrays.ContainsKey("a"));
        Assert.Equal(exported, evaluation.ExportedVariables.Contains("a"));
        Assert.Equal(readOnly, evaluation.ReadonlyVariables.Contains("a"));
        Assert.True(host.StandardOutput.Content.IsEmpty);
        Assert.Equal("line 1: declare: a: nameref variable self references not allowed\n", host.StandardError.TextContent);
        owner.Dispose();
        Assert.Equal(0, memory.ReservedBytes);
    }
